package com.milktea.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; private final Duration access,refresh; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.access-token-minutes}") long accessMinutes,@Value("${app.jwt.refresh-token-days}") long refreshDays){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));access=Duration.ofMinutes(accessMinutes);refresh=Duration.ofDays(refreshDays);} public String accessToken(UserPrincipal p){return create(p,access,"access");} public String refreshToken(UserPrincipal p){return create(p,refresh,"refresh");} private String create(UserPrincipal p,Duration ttl,String type){Instant now=Instant.now();return Jwts.builder().subject(p.username()).claim("role",p.role()).claim("type",type).issuedAt(Date.from(now)).expiration(Date.from(now.plus(ttl))).signWith(key).compact();} public Claims claims(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} public boolean isRefresh(String token){return "refresh".equals(claims(token).get("type",String.class));} }
